package br.com.cineo;
import android.widget.*;import android.view.*;import android.graphics.drawable.*;import android.graphics.*;import org.json.*;import java.util.*;import static br.com.cineo.MainActivity.*;
/** Real editorial data, rankings and public discovery; no fabricated audience counts. */
class DiscoveryScreens {
 final MainActivity a;JSONObject home=new JSONObject();VideoView trailer;FrameLayout previewHost;int previewShow=-1;DiscoveryScreens(MainActivity activity){a=activity;}
 void prepare(Runnable done){a.call("GET","/v7/home",null,r->{home=r;done.run();});}
 void release(){if(trailer!=null){trailer.stopPlayback();ViewGroup parent=(ViewGroup)trailer.getParent();if(parent!=null)parent.removeView(trailer);trailer=null;}previewShow=-1;previewHost=null;previewMedia=null;}
 void hero(LinearLayout parent,ArrayList<JSONObject> fallback){ArrayList<JSONObject> selected=new ArrayList<>();JSONArray editorial=home.optJSONArray("featured");if(editorial!=null)for(int i=0;i<editorial.length();i++)selected.add(editorial.optJSONObject(i));if(selected.isEmpty()&&!fallback.isEmpty()){int id=a.pro.homeData.optInt("featured_id");JSONObject first=fallback.get(0);for(JSONObject s:fallback)if(s.optInt("id")==id)first=s;selected.add(first);}if(selected.isEmpty())return;
  HorizontalScrollView scroll=new HorizontalScrollView(a);scroll.setHorizontalScrollBarEnabled(false);scroll.setClipToPadding(false);LinearLayout slides=a.row();slides.setGravity(Gravity.TOP);scroll.addView(slides);parent.addView(scroll,new LinearLayout.LayoutParams(-1,-2));int width=a.getResources().getDisplayMetrics().widthPixels-a.dp(40);if(selected.size()>1)width-=a.dp(18);final int slideWidth=width+a.dp(12);ArrayList<FrameLayout> posters=new ArrayList<>();
  for(JSONObject s:selected){FrameLayout hero=a.art.poster(s,410,true);posters.add(hero);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(width,a.dp(410));lp.rightMargin=a.dp(12);slides.addView(hero,lp);View shade=new View(a);shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x11090d14,0x22090d14,0xff090d14}));hero.addView(shade,new FrameLayout.LayoutParams(-1,-1));LinearLayout info=a.col();info.setPadding(a.dp(18),a.dp(16),a.dp(18),a.dp(16));a.text(info,selected.size()>1?"SELEÇÃO CINEO":"SUA PRÓXIMA HISTÓRIA",10,RED);TextView name=a.title(info,s.optString("title"),29);name.setMaxLines(2);a.text(info,s.optString("genre")+" · "+s.optString("rating")+(s.optBoolean("finished")?" · Completa":""),12,0xffdfe3eb);TextView synopsis=a.text(info,s.optString("synopsis"),13,0xffd0d8e4);synopsis.setMaxLines(2);synopsis.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout actions=a.row();Button watch=a.button(actions,"▶ Assistir",RED,()->a.startWatching(s));LinearLayout.LayoutParams first=new LinearLayout.LayoutParams(0,a.dp(48),1);first.rightMargin=a.dp(8);watch.setLayoutParams(first);a.button(actions,"Detalhes",CARD,()->a.details(s,"catalog")).setLayoutParams(new LinearLayout.LayoutParams(0,a.dp(48),1));info.addView(actions);hero.addView(info,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));Button sound=new Button(a);sound.setText("Som");sound.setTextSize(11);sound.setAllCaps(false);sound.setBackground(a.bg(0x99131c27,20));sound.setTextColor(WHITE);FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(a.dp(64),a.dp(44),Gravity.RIGHT|Gravity.TOP);sp.setMargins(0,a.dp(12),a.dp(12),0);hero.addView(sound,sp);final boolean[] audible={false};sound.setOnClickListener(v->{if(trailer!=null&&previewShow==s.optInt("id")){audible[0]=!audible[0];trailer.setOnPreparedListener(mp->{mp.setVolume(audible[0]?1:0,audible[0]?1:0);mp.setLooping(true);});if(trailer.isPlaying()){int pos=trailer.getCurrentPosition();trailer.pause();trailer.seekTo(pos);trailer.start();}if(previewMedia!=null)previewMedia.setVolume(audible[0]?1:0,audible[0]?1:0);sound.setText(audible[0]?"Mudo":"Som");}});}
  if(selected.size()>1)a.text(parent,"Deslize os destaques  •  "+selected.size()+" produções",11,MUTED);final int page=a.generation;a.handler.postDelayed(()->{if(page==a.generation)preview(selected.get(0),posters.get(0));},500);scroll.setOnScrollChangeListener((v,x,y,oldX,oldY)->{int index=Math.max(0,Math.min(selected.size()-1,(x+slideWidth/2)/slideWidth));if(previewShow!=selected.get(index).optInt("id"))preview(selected.get(index),posters.get(index));});
 }
 android.media.MediaPlayer previewMedia;
 void preview(JSONObject s,FrameLayout host){release();if(!a.playerExtras.wifi()||a.prefs.getBoolean(a.local("no_trailer"),false))return;previewShow=s.optInt("id");final int page=a.generation;a.socialRequest("GET","/v4/show/"+previewShow+"/extras",null,r->{if(page!=a.generation||previewShow!=s.optInt("id"))return;String url=r.optString("trailer_url");if(url.isEmpty())return;trailer=new VideoView(a);final VideoView current=trailer;previewHost=host;host.addView(trailer,1,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));trailer.setOnPreparedListener(mp->{if(page!=a.generation||trailer!=current)return;previewMedia=mp;mp.setVolume(0,0);mp.setLooping(true);current.start();});trailer.setOnErrorListener((mp,w,e)->{if(trailer==current)release();return true;});trailer.setVideoURI(android.net.Uri.parse(url));});}
 void shelves(LinearLayout parent){shelf(parent,"Séries completas para maratonar",home.optJSONArray("marathon"));JSONArray top=home.optJSONArray("top");if(top!=null&&top.length()>0){ArrayList<JSONObject> rows=new ArrayList<>();for(int i=0;i<top.length();i++){try{JSONObject s=new JSONObject(top.getJSONObject(i).toString());s.put("title",(i+1)+". "+s.optString("title"));rows.add(s);}catch(Exception ignored){}}a.shelf(parent,"Top da semana · espectadores reais",rows,false);}JSONArray upcoming=home.optJSONArray("upcoming");if(upcoming!=null&&upcoming.length()>0){a.title(parent,"Estreias chegando",20);for(int i=0;i<upcoming.length();i++){JSONObject s=upcoming.optJSONObject(i);a.title(parent,s.optString("title"),17);TextView countdown=a.text(parent,"",13,AMBER);final int page=a.generation;Runnable tick=new Runnable(){public void run(){if(page!=a.generation)return;try{long seconds=Math.max(0,java.time.Duration.between(java.time.Instant.now(),java.time.Instant.parse(s.optString("premiere_at"))).getSeconds());countdown.setText(seconds==0?"Estreia disponível · atualize o catálogo":"Estreia em "+seconds/86400+"d "+seconds/3600%24+"h "+seconds/60%60+"min");}catch(Exception ex){countdown.setText(a.pro.date(s.optString("premiere_at")));}a.handler.postDelayed(this,30000);}};tick.run();a.pro.followButton(parent,"show",String.valueOf(s.optInt("id")));}}
  if(!a.prefs.getBoolean(a.local("tour_done"),false)){a.gap(parent,20);a.title(parent,"Bem-vindo ao Cineo",20);a.text(parent,"Aprenda a trocar capítulos, salvar histórias e publicar sua produção.",13,MUTED);a.button(parent,"Conhecer o aplicativo",CARD,()->a.accounts.tour(0));a.button(parent,"Já conheço",BG,()->{a.prefs.edit().putBoolean(a.local("tour_done"),true).apply();a.catalog(false);});}
 }
 void shelf(LinearLayout p,String title,JSONArray data){if(data==null||data.length()==0)return;ArrayList<JSONObject> rows=new ArrayList<>();for(int i=0;i<data.length();i++)rows.add(data.optJSONObject(i));a.shelf(p,title,rows,false);}
 void guest(){a.page("guest-catalog","Conheça o Cineo","Explore histórias antes de criar sua conta.",-1,()->a.login(false));a.button(a.body,"Entrar ou criar minha conta",RED,()->a.login(false));a.call("GET","/guest",null,r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"film","Novas histórias a caminho","As produções aprovadas aparecerão aqui.");for(int i=0;i<rows.length();i++){JSONObject s=rows.getJSONObject(i);LinearLayout card=a.col();ImageView cover=new ImageView(a);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);a.image(cover,s.optString("cover_url"));card.addView(cover,new LinearLayout.LayoutParams(-1,a.dp(210)));a.title(card,s.optString("title"),22);a.text(card,s.optString("synopsis"),14,MUTED);a.text(card,s.optString("genre")+" · "+s.optString("rating"),12,MUTED);a.button(card,"Entrar para assistir",CARD,()->a.login(false));a.body.addView(card);a.gap(a.body,18);}});}
}
